```tsx
import { useEffect, useId, useRef, useState } from "react";
import "./CodeCard.css";

export interface CodeCardProps {
  title: string;
  code: string;
  onCopy: (code: string) => void;
}

type CopyState = "idle" | "copied" | "failed";

export function CodeCard({ title, code, onCopy }: CodeCardProps) {
  const titleId = useId();
  const [state, setState] = useState<CopyState>("idle");
  const resetTimer = useRef<number | undefined>(undefined);

  useEffect(() => () => window.clearTimeout(resetTimer.current), []);

  async function handleCopy() {
    try {
      if (!navigator.clipboard) {
        throw new Error("Clipboard API unavailable");
      }
      await navigator.clipboard.writeText(code);
      onCopy(code);
      setState("copied");
    } catch {
      setState("failed");
    }
    window.clearTimeout(resetTimer.current);
    resetTimer.current = window.setTimeout(() => setState("idle"), 2000);
  }

  return (
    <section className="code-card" aria-labelledby={titleId}>
      <header className="code-card__header">
        <h2 id={titleId} className="code-card__title">
          {title}
        </h2>
        <button type="button" className="code-card__copy" onClick={handleCopy}>
          Copy
        </button>
      </header>
      <pre className="code-card__code" tabIndex={0}>
        <code>{code}</code>
      </pre>
      <p className="code-card__status" role="status">
        {state === "copied" ? "Copied to clipboard." : ""}
      </p>
      <p className="code-card__status code-card__status--error" role="alert">
        {state === "failed" ? "Copy failed. Select the code and copy it by hand." : ""}
      </p>
    </section>
  );
}
